def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    marker = max((v for v in counts if v != background), key=lambda v: counts[v])
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    if not pts:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)

    # A fully formed, regularly spaced lattice is intentional and stays unchanged.
    full_cols = [c for c in range(c0, c1 + 1)
                 if all(grid[r][c] == marker for r in range(r0, r1 + 1))]
    if (all(grid[r0][c] == marker for c in range(c0, c1 + 1)) and
        all(grid[r1][c] == marker for c in range(c0, c1 + 1)) and
        len(full_cols) >= 3 and
        all(all(grid[r][c] == marker for c in full_cols)
            for r in range(r0, r1 + 1))):
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    # Join gaps on lines containing at least three foreground marks; two marks
    # alone can be opposing sides of an intentional open grid.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        if len(cols) >= 3:
            for a, b in zip(cols, cols[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        if len(rows) >= 3:
            for a, b in zip(rows, rows[1:]):
                for r in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2
    return out
